function parseRss(xml, sourceName) {
  if (!xml || typeof xml !== 'string') return [];
  const items = [];
  const blocks = xml.split(/<item[\s>]/i).slice(1);
  for (const b of blocks.slice(0, 20)) {
    const title = (b.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/i) || b.match(/<title>([\s\S]*?)<\/title>/i) || [])[1] || '';
    const link = (b.match(/<link>([\s\S]*?)<\/link>/i) || [])[1] || '';
    const desc = (b.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/i) || b.match(/<description>([\s\S]*?)<\/description>/i) || [])[1] || '';
    const pub = (b.match(/<pubDate>([\s\S]*?)<\/pubDate>/i) || [])[1] || '';
    items.push({
      source: sourceName,
      title: String(title).replace(/<[^>]+>/g, '').trim(),
      description: String(desc).replace(/<[^>]+>/g, '').trim(),
      url: String(link).trim(),
      region: 'INDIA',
      published_at: String(pub).trim()
    });
  }
  return items;
}

const newsApi = $('NewsAPI Business Headlines').first().json || {};
const articles = (newsApi.articles || []).map(a => ({
  source: (a.source && a.source.name) || 'NewsAPI',
  title: a.title || '',
  description: a.description || '',
  url: a.url || '',
  region: 'US_GLOBAL',
  published_at: a.publishedAt || ''
}));

let xml = '';
try {
  const raw = $('Moneycontrol RSS').first().json;
  if (typeof raw === 'string') xml = raw;
  else if (raw && typeof raw.data === 'string') xml = raw.data;
} catch (e) {}

const india = parseRss(xml, 'Moneycontrol');
const all = [...articles, ...india].filter(a => a.title);
return all.map(a => ({ json: a }));

